/// <summary> Устанавливает режим маржи для спота. Допустимые значения: ["0", "1"] </summary>
/// <param name="_spotMarginMode"> Режим маржи: 0=Regular margin mode, 1=Portfolio margin mode </param>
/// <returns> Режим маржи </returns>
[DataMember('spotMarginMode')]
public str parmSpotMarginMode(str _spotMarginMode = spotMarginMode)
{
    spotMarginMode = _spotMarginMode;
    return spotMarginMode;
}

